window.addEventListener('storage',event=>{
  WebFonts.onStorage(event);
  if(event.key===themeStorageKey() || event.key===null) {themeNickname='';refreshTheme();}
  if(event.key===themeEggKey() || event.key===hiddenMenuUnlockKey() || event.key===null) {
    nicknameValue='';refreshNickname();fitHeader();
  }
  if(event.key===PUSH_ENABLED_KEY && event.newValue==='false') {
    pushEnabled=false;pushSyncedSignature='';pushSyncSerial++;clearTimeout(pushSyncTimer);paintPush('다른 창에서 푸시를 껐습니다.');
  }
  if((event.key===TAB_ORDER_KEY || event.key===null) && !tabDrag) restoreTabOrder();
  if((event.key===customScope || event.key===null) && !customDirty()) {const scope=customScope, editing=customEditing;customScope='';readCustomSelection(scope);customEditing=editing;viewKey='';mainKey='';renderedKey='';tick();}
  if(event.key===alarmScope || event.key===null) {readAlarms();refreshAlarms();schedulePushSync();}
  if(event.key===REST_TABS_KEY || event.key==='BossTimer.webRest.visible' || event.key===null) {
    readRestPreferences();refreshRestFilter();renderedKey='';tick();
  }
  if(event.key==='bt_nickname' || event.key===null) {refreshNickname();fitHeader();}
  if(event.key===FIXED_TABS_KEY || event.key===null) {
    resetMasterLock();readFixedPreferences();refreshFixedFilter();mainKey='';renderedKey='';activeKey='';tick();refreshAlarms();
  }
});
